!--- style.css
:root {
    --primary-color: #A306B6;
    --primary-color-inverse: #fff;
    --grey: #D9D9D9;

    --spacing: 1rem;
    --spacing-2: calc(var(--spacing) * 2);
    --spacing-3: calc(var(--spacing) * 3);
}

* {
    box-sizing: border-box;
}

body {
    margin: 0;
    line-height: 1.5;
    background-color: #fff;
    font-family: "Source Sans 3", Verdana, Geneva, Tahoma, sans-serif;
}

h1, h2, h3 {
    font-family: "Montserrat", Verdana, Geneva, Tahoma, sans-serif;
}

h2 {
    color: var(--primary-color);
    text-align: center;
}

a {
    color: var(--primary-color);
}

img {
    max-width: 100%;
    height: auto;
}

.container {
    max-width: 800px;
    margin: auto;
    padding: 0 var(--spacing);
}

/* Style the header */
header {
    display: flex;
    flex-direction: column;
    background-color: var(--primary-color);
    color: #fff;
    text-align: center;
    min-height: 50vh;
}

header h1 {
    max-width: 8ch;
}

header .container {
    display: flex;
    flex-direction: column-reverse;
    align-items: center;
}

@media screen and (min-width: 992px) {
    header .container {
        width: 800px;
        flex-direction: row;
        justify-content: space-around;
    }

}

header .container img {
    max-width: 130px;
    border-radius: 50%;
    box-shadow: inset 0 0px 0px 4px var(--primary-color-inverse);
}

@media screen and (min-width: 992px) {
    header .container img {
        max-width: 250px;
    }

}

/* Style the navigation menu */
nav {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    background-color: var(--primary-color);
    padding: 1rem;
}

@media screen and (min-width: 992px) {
    nav {
        flex-direction: row;
        justify-content: space-between;
    }

}

nav .logo {
    width: 60px;
}

nav>ul {
    display: flex;
    list-style: none;
    padding: 0;
}

nav>ul>li>a {
    padding: 1rem;
    color: var(--primary-color-inverse);
    text-decoration: none;
}



/* Style the main section */
section.container {
    margin-top: var(--spacing-2);
    margin-bottom: var(--spacing-3);
}

section p {
    max-width: 60ch;
    margin-inline: auto;
}

/* Style section articles */
.articles {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--spacing);
}

@media screen and (min-width: 992px) {
    .articles {
        grid-template-columns: repeat(3, 1fr);
    }

}

article {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 1rem;
    background-color: var(--grey);
    border-radius: 5px;
}

article h3 {
    margin-top: auto;
}

article a {
    padding: .25rem 1.75rem;
    background-color: var(--primary-color);
    color: var(--primary-color-inverse);
    border-radius: 1rem;
    text-decoration: none;
    text-transform: uppercase;
}

article img {
    max-height: 150px;
}

/* Style the footer */
footer {
    padding: var(--spacing);
    background-color: var(--grey);
    text-align: center;
    font-size: .875rem;
}

footer p {
    margin: 0;
}

!--- index.js

import "./style.css";

